#!/usr/bin/env python3
"""Generate Doom/Playsim/FinaleText.lean from the oracle d_englsh.h
(finale texts E1TEXT..E4TEXT, C1TEXT..C6TEXT and their BEX mnemonics).

usage: gen_text.py ORACLE_SRC_DOOM_DIR OUT.lean
"""
import re, sys
from pathlib import Path
src = (Path(sys.argv[1]) / "d_englsh.h").read_text(encoding="latin-1")
names = ["E1TEXT","E2TEXT","E3TEXT","E4TEXT","C1TEXT","C2TEXT","C3TEXT","C4TEXT","C5TEXT","C6TEXT"]
out = ["/-! Finale texts from the oracle `d_englsh.h`.",
       "GENERATED by scripts/gen_text.py; do not edit. -/", "",
       "namespace Doom.Playsim.FinaleText", "",
       "/-- (BEX mnemonic, original text). -/",
       "def finaleTexts : Array (String × String) := #["]
items = []
for n in names:
    m = re.search(r"#define\s+" + n + r"\s*\\?\s*((?:\"(?:[^\"\\]|\\.)*\"\s*\\?\s*)+)", src)
    if not m:
        raise SystemExit("missing " + n)
    parts = re.findall(r"\"((?:[^\"\\]|\\.)*)\"", m.group(1))
    s = "".join(parts)
    s = s.replace("\\n", "\n").replace('\\"', '"').replace("\\'", "'")
    lean = s.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")
    items.append(f'  ("{n}", "{lean}")')
out.append(",\n".join(items))
out += ["]", "", "end Doom.Playsim.FinaleText", ""]
Path(sys.argv[2]).write_text("\n".join(out))
print("ok", len(items))
